export class Soundscape{
 constructor(){this.enabled=true;this.ctx=null;this.beat=0;this.next=0;this.boss=false;this.paused=false;}
 async start(){if(!this.ctx){const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return;this.ctx=new AC();const c=this.ctx;this.master=c.createGain();this.master.gain.value=.48;this.master.connect(c.destination);this.dry=c.createGain();this.dry.gain.value=.7;this.dry.connect(this.master);this.reverb=c.createConvolver();const len=c.sampleRate*1.8,imp=c.createBuffer(2,len,c.sampleRate);for(let ch=0;ch<2;ch++){const a=imp.getChannelData(ch);for(let i=0;i<len;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/len,3)*.3;}this.reverb.buffer=imp;const wet=c.createGain();wet.gain.value=.3;this.reverb.connect(wet);wet.connect(this.master);this.timer=setInterval(()=>this.schedule(),100);this.next=c.currentTime+.1;}if(this.ctx.state==='suspended')await this.ctx.resume();this.master.gain.setTargetAtTime(this.enabled?.48:0,this.ctx.currentTime,.05);}
 setEnabled(v){this.enabled=v;if(this.ctx)this.master.gain.setTargetAtTime(v?.48:0,this.ctx.currentTime,.08);}
 tone(freq,dur,gain=.1,type='sine',time=null,slide=null){if(!this.ctx||!this.enabled)return;const c=this.ctx,t=time??c.currentTime,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,t);if(slide)o.frequency.exponentialRampToValueAtTime(Math.max(15,slide),t+dur);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+dur);o.connect(g);g.connect(this.dry);g.connect(this.reverb);o.start(t);o.stop(t+dur+.02);}
 noise(dur=.12,gain=.12,cutoff=2500){if(!this.ctx||!this.enabled)return;const c=this.ctx,n=c.createBufferSource(),b=c.createBuffer(1,Math.ceil(c.sampleRate*dur),c.sampleRate);const a=b.getChannelData(0);for(let i=0;i<a.length;i++)a[i]=(Math.random()*2-1)*Math.pow(1-i/a.length,3);n.buffer=b;const f=c.createBiquadFilter();f.type='lowpass';f.frequency.value=cutoff;const g=c.createGain();g.gain.value=gain;n.connect(f);f.connect(g);g.connect(this.dry);n.start();n.stop(c.currentTime+dur+.01);}
 schedule(){const c=this.ctx;if(!c||c.state!=='running')return;if(this.next<c.currentTime-.2)this.next=c.currentTime+.05;const dur=this.boss?.18:.24;while(this.next<c.currentTime+.18){const roots=[45,41,38,40],bar=Math.floor(this.beat/16)%4,root=roots[bar],notes=[0,7,12,15,19,12,7,15];const midi=root+notes[this.beat%8]+12;const freq=440*Math.pow(2,(midi-69)/12),vol=this.paused?.022:.045;this.tone(freq,1.1,vol,'sine',this.next);if(this.beat%8===0){this.tone(440*Math.pow(2,(root-69)/12),2.8,.07,'triangle',this.next);this.tone(freq*.5,2.4,.035,'sine',this.next);}if(this.beat%4===2)this.tone(freq*2,.65,.014,'sine',this.next);this.next+=dur;this.beat++;}}
 play(name){if(!this.ctx||!this.enabled)return;switch(name){case'whip':this.noise(.14,.2,4500);this.tone(580,.16,.05,'triangle',null,100);break;case'swing':this.noise(.18,.08,1800);break;case'hit':this.noise(.1,.3,2400);this.tone(130,.13,.18,'triangle',null,42);this.tone(1400,.08,.04);break;case'kill':this.tone(310,.48,.10,'triangle',null,100);this.noise(.3,.08,4000);break;case'jump':this.tone(200,.16,.06,'sine',null,500);break;case'dash':this.noise(.23,.1,1000);this.tone(180,.2,.04,'sine',null,80);break;case'hurt':this.tone(170,.25,.18,'sawtooth',null,65);this.noise(.12,.12,600);break;case'magic':this.tone(540,.5,.1,'sine',null,180);this.tone(810,.45,.04);break;case'heal':case'rest':{const now=this.ctx.currentTime;[0,4,7,12].forEach((n,i)=>this.tone(440*Math.pow(2,n/12),1.2,.07,'sine',now+i*.12));break;}case'charge':this.tone(90,1,.08,'triangle',null,180);break;case'boss':this.tone(55,3,.16,'triangle');this.tone(82.4,3,.1,'sine');break;}}
}
